package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.Bundle;import java.io.*;import java.util.*;
/** Local APK preview; installation always remains in Android's trusted confirmation UI. */
public final class ApkInstallActivity extends LeoActivity {
 private File file;private PackageInfo archive;private String fingerprint="";
 protected void onCreate(Bundle b){super.onCreate(b);String path=getIntent().getStringExtra("file");if(path==null){notice(L.t("Alege un APK din Fișiere Leo"));finish();return;}file=new File(path);load();}
 static boolean allowed(Context c,File f)throws IOException{if(!f.isFile()||!f.getName().toLowerCase(Locale.ROOT).endsWith(".apk")||java.nio.file.Files.isSymbolicLink(f.toPath()))return false;for(File root:LeoFileProvider.roots(c).values())if(LeoFileProvider.inside(root,f))return true;return false;}
 private void load(){begin(L.t("Verific APK-ul"));root.addView(text(L.t("Se citesc pachetul și certificatul…"),18));footer("","",L.t("Înapoi"));worker.execute(new Runnable(){public void run(){try{if(!allowed(ApkInstallActivity.this,file))throw new IOException();final PackageInfo info=getPackageManager().getPackageArchiveInfo(file.getAbsolutePath(),PackageManager.GET_PERMISSIONS|PackageManager.GET_SIGNATURES);if(info==null)throw new IOException();info.applicationInfo.sourceDir=file.getAbsolutePath();info.applicationInfo.publicSourceDir=file.getAbsolutePath();String cert=L.t("Indisponibil");if(info.signatures!=null&&info.signatures.length>0)cert=BackupEngine.hash(info.signatures[0].toByteArray());final String digest=cert;ui(new Runnable(){public void run(){archive=info;fingerprint=digest;show();}});}catch(Exception e){ui(new Runnable(){public void run(){notice(L.t("APK invalid sau inaccesibil"));finish();}});}}});}
 private void show(){ArrayList<String> rows=new ArrayList<String>();rows.add(L.t("Instalează · confirmare Android"));rows.add(L.t("Permisiuni cerute"));rows.add(L.t("Permite instalări din Leo (Android)"));rows.add(archive.applicationInfo.loadLabel(getPackageManager())+"\n"+archive.packageName);rows.add(L.t("Versiune · ")+archive.versionName+" ("+archive.versionCode+")");rows.add("APK · "+android.text.format.Formatter.formatFileSize(this,file.length()));rows.add(L.t("Certificat SHA-256\n")+fingerprint);list(L.t("Instalare APK"),rows,0,new Choice(){public void pick(int n){if(n==0)confirm();else if(n==1){ArrayList<String> permissions=new ArrayList<String>();if(archive.requestedPermissions!=null)permissions.addAll(Arrays.asList(archive.requestedPermissions));options(L.t("Permisiuni solicitate"),permissions.isEmpty()?new String[]{L.t("Niciuna")}:permissions.toArray(new String[0]),new Choice(){public void pick(int i){}});}else if(n==2)try{startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));}catch(RuntimeException e){notice(L.t("Pagina Android nu este disponibilă"));}}},"",null);}
 private void confirm(){options(L.t("Deschizi instalatorul pentru ")+archive.packageName+"?",new String[]{L.t("Anulează"),L.t("Continuă în Android")},new Choice(){public void pick(int n){if(n!=1)return;try{if(!getPackageManager().canRequestPackageInstalls()){notice(L.t("Permite întâi instalările din Leo"));return;}Uri uri=LeoFileProvider.uri(ApkInstallActivity.this,file);Intent install=new Intent(Intent.ACTION_INSTALL_PACKAGE).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra(Intent.EXTRA_RETURN_RESULT,true);install.setClipData(ClipData.newRawUri(L.t("APK ales"),uri));startActivityForResult(install,61);}catch(Exception e){notice(L.t("Instalatorul Android nu este disponibil"));}}});}
 protected void onActivityResult(int r,int code,Intent i){super.onActivityResult(r,code,i);if(r==61){notice(code==RESULT_OK?L.t("Instalare terminată"):L.t("Instalare anulată sau nereușită"));show();}}
}
